"""
Settings routes for the admin dashboard.

All state-mutating endpoints (PUT, POST) are protected with the
@csrf_protect decorator from app.csrf.  Read-only GET endpoints are
intentionally left undecorated because they do not change server state.

CSRF token lifecycle
--------------------
1. Client calls  GET /api/settings/csrf-token  (authenticated session required).
2. Server generates (or returns existing) session-bound token.
3. Client includes the token on every mutating request as either:
     - Header:     X-CSRF-Token: <token>
     - Form field: csrf_token=<token>
     - JSON body:  {"csrf_token": "<token>", ...}
4. Server validates with HMAC-SHA256 before processing the request.
"""

from flask import Blueprint, request, jsonify

from app.csrf import csrf_protect, generate_csrf_token

settings_bp = Blueprint('settings', __name__, url_prefix='/api/settings')


# ---------------------------------------------------------------------------
# CSRF token issuance (GET — no mutation, no CSRF check needed)
# ---------------------------------------------------------------------------

@settings_bp.route('/csrf-token', methods=['GET'])
def get_csrf_token():
    """Return a CSRF token bound to the current authenticated session."""
    return jsonify({'csrf_token': generate_csrf_token()})


# ---------------------------------------------------------------------------
# Mutating settings endpoints — all decorated with @csrf_protect
# ---------------------------------------------------------------------------

@settings_bp.route('/allowed-ips', methods=['GET'])
def get_allowed_ips():
    """Return the current allowed-IP configuration (read-only)."""
    # TODO: load from config store
    return jsonify({'allowed_ips': []})


@settings_bp.route('/allowed-ips', methods=['PUT'])
@csrf_protect
def update_allowed_ips():
    """
    Replace the allowed-IP whitelist.

    Expects JSON body: {"allowed_ips": ["1.2.3.4", "10.0.0.0/8"]}
    """
    data = request.get_json(force=True)
    # TODO: validate and persist allowed_ips
    return jsonify({'status': 'ok', 'allowed_ips': data.get('allowed_ips', [])})


@settings_bp.route('/backup', methods=['GET'])
def get_backup_settings():
    """Return current backup configuration (read-only)."""
    # TODO: load from config store
    return jsonify({'backup_enabled': True, 'schedule': 'daily'})


@settings_bp.route('/backup', methods=['POST'])
@csrf_protect
def configure_backup():
    """
    Update backup settings.

    Expects JSON body: {"backup_enabled": true, "schedule": "daily"}
    """
    data = request.get_json(force=True)
    # TODO: validate and persist backup config
    return jsonify({'status': 'ok', 'backup_enabled': data.get('backup_enabled'),
                    'schedule': data.get('schedule')})


@settings_bp.route('/general', methods=['GET'])
def get_general_settings():
    """Return general application settings (read-only)."""
    # TODO: load from config store
    return jsonify({'site_name': '', 'maintenance_mode': False})


@settings_bp.route('/general', methods=['PUT'])
@csrf_protect
def update_general_settings():
    """
    Update general application settings.

    Expects JSON body: {"site_name": "MyApp", "maintenance_mode": false}
    """
    data = request.get_json(force=True)
    # TODO: validate and persist general settings
    return jsonify({'status': 'ok', 'site_name': data.get('site_name'),
                    'maintenance_mode': data.get('maintenance_mode')})


@settings_bp.route('/notifications', methods=['GET'])
def get_notification_settings():
    """Return notification settings (read-only)."""
    return jsonify({'email_alerts': True, 'webhook_url': ''})


@settings_bp.route('/notifications', methods=['PUT'])
@csrf_protect
def update_notification_settings():
    """
    Update notification / alerting settings.

    Expects JSON body: {"email_alerts": true, "webhook_url": "https://..."}
    """
    data = request.get_json(force=True)
    # TODO: validate and persist notification config
    return jsonify({'status': 'ok', 'email_alerts': data.get('email_alerts'),
                    'webhook_url': data.get('webhook_url')})

"""
Admin Dashboard — Settings endpoint tests.
Updated to include the CSRF token header required after CSRF protection was added.
"""
import pytest


@pytest.fixture
def csrf_token(client):
    """Obtain a valid CSRF token from the token endpoint."""
    resp = client.get("/api/csrf-token")
    assert resp.status_code == 200
    return resp.get_json()["csrf_token"]


@pytest.fixture
def auth_headers(client, csrf_token):
    """Return headers that satisfy both authentication and CSRF checks."""
    return {
        "Authorization": "Bearer test-admin-token",
        "X-CSRF-Token": csrf_token,
        "Content-Type": "application/json",
    }


# ---------------------------------------------------------------------------
# GET endpoints — CSRF token NOT required (read-only)
# ---------------------------------------------------------------------------

class TestSettingsRead:
    def test_get_settings_returns_200(self, client):
        resp = client.get(
            "/api/admin/settings",
            headers={"Authorization": "Bearer test-admin-token"},
        )
        assert resp.status_code == 200

    def test_get_settings_structure(self, client):
        resp = client.get(
            "/api/admin/settings",
            headers={"Authorization": "Bearer test-admin-token"},
        )
        data = resp.get_json()
        assert "settings" in data


# ---------------------------------------------------------------------------
# POST / PUT / DELETE endpoints — CSRF token IS required
# ---------------------------------------------------------------------------

class TestUpdateSettings:
    def test_update_settings_with_valid_csrf(self, client, auth_headers):
        resp = client.post(
            "/api/admin/settings",
            json={"theme": "dark"},
            headers=auth_headers,
        )
        assert resp.status_code == 200

    def test_update_settings_without_csrf_returns_403(self, client):
        resp = client.post(
            "/api/admin/settings",
            json={"theme": "dark"},
            headers={
                "Authorization": "Bearer test-admin-token",
                "Content-Type": "application/json",
            },
        )
        assert resp.status_code == 403

    def test_update_settings_with_invalid_csrf_returns_403(self, client):
        resp = client.post(
            "/api/admin/settings",
            json={"theme": "dark"},
            headers={
                "Authorization": "Bearer test-admin-token",
                "X-CSRF-Token": "invalid-token-value",
                "Content-Type": "application/json",
            },
        )
        assert resp.status_code == 403

    def test_update_settings_with_empty_csrf_returns_403(self, client):
        resp = client.post(
            "/api/admin/settings",
            json={"theme": "dark"},
            headers={
                "Authorization": "Bearer test-admin-token",
                "X-CSRF-Token": "",
                "Content-Type": "application/json",
            },
        )
        assert resp.status_code == 403


class TestDeleteSettings:
    def test_delete_setting_with_valid_csrf(self, client, auth_headers):
        resp = client.delete(
            "/api/admin/settings/theme",
            headers=auth_headers,
        )
        assert resp.status_code in (200, 204)

    def test_delete_setting_without_csrf_returns_403(self, client):
        resp = client.delete(
            "/api/admin/settings/theme",
            headers={"Authorization": "Bearer test-admin-token"},
        )
        assert resp.status_code == 403


class TestUpdateNotifications:
    """Notification preferences live under /api/admin/settings/notifications."""

    def test_update_notifications_with_valid_csrf(self, client, auth_headers):
        resp = client.put(
            "/api/admin/settings/notifications",
            json={"email_alerts": True},
            headers=auth_headers,
        )
        assert resp.status_code == 200

    def test_update_notifications_without_csrf_returns_403(self, client):
        resp = client.put(
            "/api/admin/settings/notifications",
            json={"email_alerts": True},
            headers={
                "Authorization": "Bearer test-admin-token",
                "Content-Type": "application/json",
            },
        )
        assert resp.status_code == 403
